const items     = [];
const seenLinks = new Set();

for (const input of $input.all()) {
  // HTTP Request stores the body in different places depending on content-type
  const raw = input.json.data || input.json.body
    || (typeof input.json === 'string' ? input.json : '')
    || JSON.stringify(input.json);

  const xml = typeof raw === 'string' ? raw : '';
  if (!xml || !xml.includes('<item')) continue;

  for (const m of xml.matchAll(/<item[^>]*>([\s\S]*?)<\/item>/gi)) {
    const block = m[1];
    const tag = name => {
      const r = block.match(
        new RegExp(`<${name}[^>]*>(?:<!\\[CDATA\\[)?([\\s\\S]*?)(?:\\]\\]>)?<\\/${name}>`, 'i')
      );
      return r ? r[1].trim() : '';
    };

    const link  = tag('link') || tag('guid');
    let   title = tag('title')
      .replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&#039;/g,"'").replace(/&quot;/g,'"');
    const desc  = tag('description')
      .replace(/<[^>]+>/g,'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').trim().slice(0,400);
    const pubDate = tag('pubDate');

    let imageUrl = '';
    const imgM = block.match(/media:content[^>]+url="([^"]+)"/i)
               || block.match(/enclosure[^>]+url="([^"]+)"/i);
    if (imgM) imageUrl = imgM[1];

    if (!link || !title || seenLinks.has(link)) continue;
    seenLinks.add(link);
    items.push({ title, link, desc, pubDate, imageUrl });
  }
}

// Sort newest first, take top 5
items.sort((a,b) => {
  const da = a.pubDate ? new Date(a.pubDate) : new Date(0);
  const db = b.pubDate ? new Date(b.pubDate) : new Date(0);
  return db - da;
});

if (items.length === 0) {
  throw new Error('No RSS articles found. Check that at least one RSS feed is reachable.');
}

return items.slice(0, 5).map(a => ({ json: a }));

const { execSync } = require('child_process');
const fs = require('fs');

// ── Get AI response ───────────────────────────────────────────────────────────
const item = $input.first().json;

// ── Get original article data from the loop ───────────────────────────────────
let origTitle = '', origDesc = '', imageUrl = '';
try {
  const loopItem = $('One At A Time').first().json;
  origTitle = loopItem.title  || '';
  origDesc  = loopItem.desc   || '';
  imageUrl  = loopItem.imageUrl || '';
} catch(e) {}

// ── Parse AI JSON response ────────────────────────────────────────────────────
let aiText = '';
try { aiText = item.choices[0].message.content || ''; } catch(e) {}

let parsed = null;

// Handle markdown code block or raw JSON
const cbMatch = aiText.match(/```(?:json)?\s*([\s\S]*?)```/);
if (cbMatch) {
  try { parsed = JSON.parse(cbMatch[1].trim()); } catch(e) {}
}
if (!parsed) {
  const braceMatch = aiText.match(/(\{[\s\S]*\})/);
  if (braceMatch) {
    try { parsed = JSON.parse(braceMatch[1].trim()); } catch(e) {}
  }
}
if (!parsed) {
  try { parsed = JSON.parse(aiText.trim()); } catch(e) {}
}

// ── Fallback if AI fails ──────────────────────────────────────────────────────
if (!parsed || !parsed.headline) {
  const upper   = origTitle.toUpperCase().slice(0, 80);
  const isCVE   = /cve|vuln|exploit|zero.?day|breach|hack/i.test(origTitle);
  const isPatch = /patch|update|fix|release/i.test(origTitle);
  parsed = {
    template:    isCVE ? 1 : (isPatch ? 2 : 3),
    headline:    upper,
    badge:       isCVE ? 'SECURITY ALERT' : (isPatch ? 'SECURITY UPDATE' : 'SECURITY GUIDE'),
    pills:       [],
    body:        origDesc.slice(0, 200),
    description: origDesc.slice(0, 300),
    caption:     `${origDesc.slice(0, 250)}\n\n#CyberRangeLabs #CyberSecurity #InfoSec #Hacking`
  };
}

// ── Sanitise fields ───────────────────────────────────────────────────────────
parsed.template    = parseInt(parsed.template) || 1;
if (![1,2,3].includes(parsed.template)) parsed.template = 1;
parsed.image_url   = imageUrl;
parsed.output_path = '/root/Desktop/crl_output.png';
if (!parsed.caption) {
  parsed.caption = `${origDesc.slice(0, 250)}\n\n#CyberRangeLabs #CyberSecurity #InfoSec`;
}

// ── Run Python image generator ────────────────────────────────────────────────
const jsonStr = JSON.stringify(parsed).replace(/'/g, "'\\''");
const cmd     = `python3 /root/Desktop/crl_poster.py '${jsonStr}'`;

let imgPath = '/root/Desktop/crl_output.png';
try {
  const out = execSync(cmd, { encoding: 'utf8', timeout: 60000 }).trim();
  if (out && out.endsWith('.png')) imgPath = out;
} catch(e) {
  throw new Error('Python script failed: ' + e.message.slice(0, 500));
}

if (!fs.existsSync(imgPath)) {
  throw new Error('Output image not found at: ' + imgPath);
}

// ── Read image → base64 ───────────────────────────────────────────────────────
const b64 = fs.readFileSync(imgPath).toString('base64');

return [{
  json: { caption: parsed.caption, image_path: imgPath },
  binary: {
    photo: {
      data:     b64,
      mimeType: 'image/png',
      fileName: 'crl_post.png'
    }
  }
}];

const fs = require('fs');
const SEEN_FILE = '/root/.crl_seen_links.json';

// Load seen links (set of URLs, max last 500 kept)
let seen = [];
try { seen = JSON.parse(fs.readFileSync(SEEN_FILE, 'utf8')); } catch(e) {}
const seenSet = new Set(seen);

// Filter out articles already seen
const newItems = [];
for (const item of $input.all()) {
  const link = item.json.link || '';
  if (link && seenSet.has(link)) continue;
  newItems.push(item);
}

if (newItems.length === 0) {
  // Nothing new — end workflow gracefully
  return [];
}

// Persist newly seen links (keep last 500)
for (const item of newItems) {
  const link = item.json.link || '';
  if (link) seen.push(link);
}
const trimmed = seen.slice(-500);
fs.writeFileSync(SEEN_FILE, JSON.stringify(trimmed));

return newItems;
